import {g} from './shared.js';
export const trainingGuides=[
g('pretraining','如果每来一个任务都只靠几百条示范从零学习，模型既要学语言/视觉规律，又要学任务，通常信号不够。预训练先利用更广的数据建立可复用能力，再作为后续任务的起点。',
 ['做客服前，先积累语言阅读能力和产品常识；入职培训才教工单格式。两种训练解决的问题不同。','模型并不真正入学；它仍在优化可计算的目标，不能由“读过资料”推断理解正确。'],
 ['原文“今天 下雨 了”构造“今天→下雨”“今天 下雨→了”。','让模型给真实后续更高概率，在很多文本上累积更新。','保存基座；另外测试未见文本，不能用训练句子续写漂亮作为唯一证据。'],
 ['先选模态与监督目标：next-token、去噪或表征目标。','定义数据划分、去重、有效 token/图像预算；建立小规模基线。','保存模型、优化器、数据状态与固定评测，作为继续训练起点。'],
 '大量数据可以共享到多个下游任务，减少每个任务重新学表示的工作。','数据与算力成本高，质量、偏差与记忆都会影响基座；预训练完成不保证会遵循指令。',
 ['能续写文章却不返回 JSON，是预训练没有发生吗？','不一定。续写能力与任务规范是不同目标，先测试格式要求，再选择提示、约束或后训练。']),
g('posttraining','基座会生成合理文本，不代表会服从输出规范、选择高质量答案或完成行动。后训练围绕这些使用要求，继续塑造模型行为和能力。',
 ['会写中文的人仍需练习如何填写一张格式严格的报销单；会填格式也不代表金额一定正确。','后训练不是只改风格；参数更新可能影响事实、推理和原有能力。'],
 ['同题两个回答都通顺，但只有一个有资料依据。','SFT 可示范有依据的回答，偏好训练可比较优劣，奖励可检查可执行结果。','训练后分别测格式、正确性、旧能力与成本，不把一项提升叫全面提升。'],
 ['写明具体失败及不训练的基线。','按可获得信号选择示范、偏好、奖励或教师分布。','固定评测比较更新前后，保留可回退 checkpoint。'],
 '能把已有能力集中到具体任务，通常比为任务从零训练更可行。','监督偏差、奖励漏洞与遗忘可能被放大；不存在所有模型必须经过的统一算法顺序。',
 ['后训练必须等于 SFT→DPO→RL 吗？','不必。路线取决于起点、反馈与目标，某些步骤可省略或采用不同顺序。']),
g('continual-pretraining','基座未充分见过专业资料时，直接教回答格式可能补不了领域分布。持续预训练从已有权重继续学习预训练类目标，让模型更多接触该领域。',
 ['已经会阅读，再读机械维修资料；此时仍在熟悉语言和内容，尚未练习某份维修报告的固定模板。','阅读专业资料不保证可靠记住每条事实；需要检索与评测判断实际收益。'],
 ['同一基座 A 分出 B、C。','B 用 30% 领域原文，C 用 90%，保持新增有效 token 预算一致。','分别测通用与领域 loss；领域改善但通用退化，是需要报告的权衡。'],
 ['核对 tokenizer、原文切块、起始权重和学习率日程。','说明是否恢复优化器；记录通用/领域抽样比例。','用相同保留集选择停止点，比较是否真的需要进入 SFT。'],
 '可在较少结构改动下补充领域分布，也可用于某些中训练配方。','小领域数据重复过多会过拟合；CPT 是操作类型，不与所有项目的 mid-training 完全同义。',
 ['只因接着训练就可以叫 SFT 吗？','不能。继续预测原文与根据指令示范训练，要看样本格式、监督位置和使用目标。']),
g('training-inference','修改参数和使用参数是两个不同过程。混淆后，就容易把改提示、检索资料或生成更久误认为模型已经重新学习。',
 ['调好厨房秤的校准参数后称苹果，是使用；根据砝码误差重新校准，是调整参数。','推理也会更新缓存或任务状态；状态变化通常不等于模型权重被训练。'],
 ['w=2、b=1，输入 x=3，输出 7：推理。','目标为 9，算 loss、梯度并把 w 改为 2.1：训练。','下次输入仍为 3，输出变为 7.3；要检查变的是权重还是仅输入。'],
 ['沿代码找 forward 与 optimizer.step。','区分 model.eval()、no_grad() 和冻结参数的职责。','记录推理使用的 checkpoint、adapter、提示和解码配置。'],
 '分清过程后，可以独立调试训练、服务与缓存，减少错误归因。','训练和推理的数据分布或模板不一致会使离线效果无法复现；eval 模式本身不关闭求导。',
 ['往上下文加入一本手册，是更新模型参数吗？','通常不是，是推理时提供信息。是否训练要看是否根据目标执行参数更新。']),
g('pt','同一组缩写在不同团队可能指不同阶段；直接猜含义会把数据、目标和排错方向都看错。PT 先作为待查证标签处理。',
 ['同事说“去 QA”，可能指测试部门，也可能指质量审核流程；首字母不足以定位工作。','不能因为其他公司用某含义，就套用到当前仓库。'],
 ['看到 pt.yaml，只能确认文件名。','继续找输入 checkpoint、数据模板、loss 和 trainable 参数。','如果是原文 next-token，可支持预训练类操作判断；若是指令示范，则是另一类证据。'],
 ['找作者全称或运行说明。','读取真实配置与训练入口，标出证据位置。','仍不确定就保留未知，不用猜测填满概念图。'],
 '避免缩写误解，把讨论转成可复查操作。','名称本身没有可比较的算法优缺点；未确认前不能推荐该“方法”。',
 ['目录名 PT 能证明训练用什么 loss 吗？','不能。必须追踪实际样本和损失实现。']),
g('sft','通用续写目标不保证模型把“请输出三项”当作任务。SFT 用输入和正确示范输出，直接告诉已有模型怎样完成这类任务。',
 ['师傅给出几张“订单→规范工单”，新人照着练习。示范必须覆盖例外，不能每张都照搬同一句。','模型不是逐字背规则的程序；学到的是条件概率，仍会出错。'],
 ['输入“把红块移到 0.2”，答案是规定字段的 JSON。','prompt 作为上下文；回答 token 可参与交叉熵，padding 不参与。','同义改写与未见位置放到评测，分开测 JSON 合法和任务正确。'],
 ['先写任务契约和十条可靠示范，检查歧义与冲突。','展开模板、input_ids、labels 与 mask，确保目标没有错位。','对照基座/全量 SFT/LoRA，保持数据和评测一致。'],
 '流程直观，能学习格式、指令和领域任务，也便于定位标签问题。','受示范覆盖与质量限制；训练 loss 降低可能只是记住模板，且可能损伤旧能力。',
 ['指令位置不计 loss，模型还能读取指令吗？','能。可见性由注意力规则控制，计分位置由 loss mask 控制。']),
g('lora','全量微调要存储大量梯度和优化器状态。LoRA 冻结原矩阵 W，用较小的 A、B 学习增量，让任务适配的可训练部分变小。',
 ['现成配方旁放一张小调整单，按任务加一点盐或减一点糖，原配方仍保留。','真实 LoRA 是低秩矩阵增量，不是为每个输入临时写提示；小调整单也不保证足以表达全部改动。'],
 ['W 为 4×3，有 12 个参数；rank=1 时 A 为 1×3、B 为 4×1，共 7 个可训练参数。','计算 y=Wx+(alpha/r)B(Ax)，输入输出接口不变。','冻结 W，只更新 A/B；改变 rank 会改变增量表达空间和成本。'],
 ['选择目标线性层，记录 rank、alpha 和初始化。','检查 requires_grad、optimizer 参数组和更新前后差值。','保存 adapter 与基座版本，推理时正确加载或按支持条件合并。'],
 '节省可训练状态，便于保存多个任务适配器；可以与 SFT 等目标组合。','底座与激活仍占内存，rank 和目标层可能限制效果；参数少不保证延迟按比例降低。',
 ['SFT 与 LoRA 能一起用吗？','可以。SFT 规定示范任务与监督目标，LoRA 规定哪些参数以什么形式更新。']),
g('qlora','LoRA 减少训练状态，却仍需存放基础权重。QLoRA 进一步用量化存储冻结底座，同时训练低秩适配器，降低适配大模型的内存需求。',
 ['把厚手册压缩存放，旁边保留精细的修改笔记；每次使用时仍要把压缩内容变成可计算的表示。','低比特存储不代表所有运算都用 4 bit，也不意味着完全无数值误差。'],
 ['假设十亿个权重：仅按原始存储，16 bit 约 2 GB，4 bit 约 0.5 GB。','真实还要量化元数据、adapter、激活、梯度与优化器状态，不能把 0.5 GB 当总显存。','在相同任务上与高精度 LoRA 比质量、显存和速度。'],
 ['确认量化格式、支持的硬件和计算 dtype。','冻结量化底座，核对 adapter 与精度配置。','实际测峰值显存和任务表现，记录保存/加载兼容性。'],
 '在内存受限时可能让原本装不下的适配训练变得可行。','有量化误差与实现限制；节省存储不自动带来加速，合并/再量化也要验证。',
 ['QLoRA 的 4 bit 意味着所有激活都 4 bit 吗？','不是。基础权重存储、计算精度和可训练参数精度要分开核对。']),
g('reward','只有示范时，模型知道某个答案怎么写，却未必知道自己产生的另一答案好不好。奖励把一次行为或轨迹的评价变成可计算的反馈。',
 ['导航任务把到达目标记为 +1，撞墙记为负分；若只奖励移动距离，原地绕圈也可能拿高分。','分数代表你写的代理标准，不等于真实目标天然被精确描述。'],
 ['回答 A 通过测试得 1，B 不通过得 0。','策略采样 A/B 后，训练可倾向提高高回报行为的概率。','增加隐藏测试，检查是否靠硬编码答案钻公开测试漏洞。'],
 ['写出真实目标，再选择可测代理信号。','列出至少两个高奖励但任务失败的反例。','用独立评测监控奖励提升是否对应实际改进。'],
 '能利用结果反馈优化没有唯一标准答案的行为。','奖励可能稀疏、有噪声或可投机；数值范围和长度偏差也会影响训练。',
 ['reward 上升就表示任务更好吗？','不一定。要检查独立成功率、代价和奖励漏洞。']),
g('reward-model','人工不能给策略产生的每条新回答打分。奖励模型学习人类或其他标签的评价规律，为更多候选提供近似分数。',
 ['先请评审比较一批作文，再训练一个自动评分器；评分器可能学会偏爱长句，而不是更可靠的内容。','它是学习出的代理，不是一个保证正确的裁判。'],
 ['同题 chosen/rejected 的评分为 2 和 0，差值为 2。','sigmoid(2)≈0.881，表示该排序在配对模型下的概率；不是答案有 88.1% 正确。','保留新的偏好对检查排序，再用独立任务验证策略。'],
 ['核对同题候选、偏好标签一致性与数据划分。','训练配对目标，检查长度、风格和群体偏差。','冻结评分器后训练策略，持续查 reward hacking。'],
 '把昂贵人工评价扩展到更多生成样本。','有分布外失效与偏差放大；策略会主动找到评分器薄弱处。',
 ['两个奖励模型的绝对分数能直接比较吗？','通常不能。标定、目标和训练数据不同，应看同一协议下的排序或任务评测。']),
g('rlhf','许多回答没有唯一标准文本，但人能比较哪条更有帮助。RLHF 将人类反馈转为策略改进的信号，是反馈来源与训练流程的描述。',
 ['厨师尝试多种菜式，由顾客比较口味，再调整做法；顾客偏好可能彼此冲突。','模型优化的是收集到的反馈，不代表所有人的统一价值判断。'],
 ['为同题回答收集人类偏好。','一种常见路线先训练奖励模型，再让策略采样、评分并更新。','比较帮助程度之外，还检查事实、长度和原有能力是否退化。'],
 ['明确标注标准、覆盖人群与冲突处理。','核对奖励模型和策略评测是否隔离。','选择实际优化算法，记录参考策略、KL 与采样预算。'],
 '能表达难以手写精确规则的质量偏好。','反馈昂贵且主观，奖励代理与策略优化都会引入误差；不等同于 PPO 一个算法。',
 ['PPO 就是 RLHF 吗？','不是。PPO 是优化算法，RLHF 描述人类反馈驱动的范式；反馈还可以来自规则或环境。']),
g('dpo','常见 RLHF 流程含奖励模型和在线 rollout，工程较复杂。有固定偏好对时，普通离线 DPO 直接优化偏好排序对应的策略目标。',
 ['同一道菜有 A/B 两版，评审选 A；厨师根据配对比较调整，而不是先另外造一个能给所有菜打分的系统。','偏好比较仍是噪声数据；“直接”不表示没有参考模型或训练成本。'],
 ['参考策略对 chosen/rejected 的 log 概率差为 0.2，新策略差为 0.6。','相对差为 0.4，乘 beta 后进入 sigmoid 与负对数损失。','它鼓励相对偏好改进，不能只看 chosen 的绝对概率。'],
 ['确保一对候选针对同一输入，检查标签和长度偏差。','固定参考策略，核对 token log-prob 与序列汇总。','在独立偏好和任务指标上比较，不仅看 DPO loss。'],
 '固定偏好数据可直接用于训练，普通离线形式无需独立奖励模型和优化期在线采样。','受偏好数据覆盖限制，参考模型、beta 和长度处理影响结果；不自动探索新好答案。',
 ['把 rejected 换成另一个问题的答案行吗？','不行。同题比较的意义被破坏，模型可能只学会输入不匹配的捷径。']),
g('ppo','策略一次更新过大，旧采样数据就可能不再适合评价新策略。PPO 用旧新动作概率比和裁剪替代目标，控制继续鼓励某些过大更新的程度。',
 ['试菜后每轮调整有节制，比一次把所有调料翻倍更容易判断反馈。','裁剪目标不是硬性保证参数或概率只能移动某个幅度，也不保证训练稳定。'],
 ['ratio=1.5、优势 A=2、epsilon=0.2。','未裁剪项=3，裁剪项=2.4，取 min 得 2.4；最小化 loss 时取负号。','A=-2、ratio=0.5 时 min(-1,-1.6)=-1.6，不能忽略负优势。'],
 ['保存采样时同动作的 old log-probability。','估计回报/优势，核对裁剪、KL、价值项等实际配方。','更新后重新采样，测成功率、KL、熵和成本。'],
 '可复用一批采样做多次更新，是应用广泛的策略优化思路。','对优势、奖励尺度与数据新鲜度敏感；单个裁剪公式不是完整 PPO。',
 ['直接把 ratio 裁剪后乘 A 就够了吗？','不够，还要与未裁剪项取 min；负优势时差异尤其明显。']),
g('grpo','为每条输出训练单独价值估计器会增加资源与实现成本。原始 GRPO 利用同题一组回答的相对奖励估计优势，减少单独价值模型需求。',
 ['同题生成四份解法，先比较这四份谁更好；相对名次可提供反馈，但四份全错且同分时信息很少。','组内比较不是答案正确性的来源，奖励规则仍必须可靠。'],
 ['同题奖励 [0,1,1,2]，均值 1，中心化后 [-1,0,0,1]。','若配方要求标准化，再除以有保护项的标准差；不同变体处理不同。','全组 [1,1,1,1] 的中心化信号为零，不能除零。'],
 ['固定同题分组与 rollout 条数，检查奖励是否可区分。','按具体版本实现归一化、ratio、KL 和 token 聚合。','独立测试真实正确率，监控长度、方差和零信号比例。'],
 '用组内相对反馈提供学习信号，减少单独价值网络的负担。','组采样有成本；同分、噪声、长度偏差会削弱信号，不能保证奖励可靠。',
 ['GRPO 与 RLVR 是同义词吗？','不是。GRPO 描述优化方式，RLVR 描述奖励可由规则验证。']),
g('distillation','大教师的推理成本或部署条件不适合目标场景。蒸馏用教师输出、概率或特征指导学生，希望把部分行为迁移到更合适的模型。',
 ['老师除了给正确答案，还告诉学生“这个选项接近正确，另一个完全不对”，反馈比只有标签更细。','学生不保证继承教师全部知识；教师的错误也可能被复制。'],
 ['教师类别概率 [0.7,0.2,0.1]，学生 [0.4,0.3,0.3]。','用分布损失让学生靠近教师，可保留第二候选的信息。','再用真实标签和独立任务评测，防止只证明模仿老师。'],
 ['决定蒸馏答案、logits、特征还是轨迹。','对齐输入、词表、温度和有效位置。','比较学生原始性能、蒸馏后性能与实际成本。'],
 '可利用细粒度教师信号，压缩或整合已有能力。','教师推理可能昂贵；容量差异、域偏移和对齐错误限制效果。',
 ['蒸馏 loss 很低证明学生正确吗？','只说明更像所选教师信号，还需独立任务验收。']),
g('mopd','多个领域教师各擅长一项，直接混合参数可能损伤能力；只学教师自己的轨迹又会遇到学生部署时的前缀差异。MOPD 让匹配教师评价学生自己的 rollout。',
 ['学生先做数学或编程题，再让对应科目的老师点评学生实际写出的步骤，不是把两位老师的笔记随机拼起来。','比喻不代表学生获得所有专长，整合收益必须逐域测量。'],
 ['学生在某前缀采样 token x，log p_student(x)=-2。','领域教师在相同前缀评价相同 x，log p_teacher(x)=-1，差值为 +1。','这个单 token 信号不是完整分布 KL；仍需按算法实现估计和梯度。'],
 ['确认是 Multi-Teacher On-Policy Distillation，核对具体版本。','建立领域教师、学生采样、教师路由、对齐与 mask。','逐域比较整合前后及采样成本，不只报平均分。'],
 '能用学生实际访问的上下文获得领域教师的细粒度反馈。','教师与 rollout 成本高，学生容量和域冲突仍有限制；教学解析教师实验不是完整论文复现。',
 ['MOPD 可以替换 KDA 层吗？','不能直接替换。MOPD 是训练路线，KDA 是序列计算机制，处在不同层。']),
g('mopd-prompts','软提示适配可能在见过的类别上表现好、未见类别上退化。Mixture-of-Prompts Distillation 研究如何把手工提示的知识迁移到可学习提示。',
 ['为不同对象准备几种描述模板，再学习在具体输入上借鉴哪些模板；类似比较“照片中的…”与“素描中的…”。','它不是学生语言模型向多个 RL 教师学习的那篇 MOPD。'],
 ['一个图文模型面对同一类别，可用不同手工文本提示。','该研究利用提示蒸馏与门控选择来学习软提示。','分别评测已见和未见类别，不能只看训练类提升。'],
 ['先核对全称、论文年份和模型输入。','按论文追踪硬提示、软提示与门控的可训练部分。','保留跨类别评测并与普通提示学习对照。'],
 '为视觉语言适配中的未见类别泛化提供研究路线。','依赖具体提示与数据设置；缩写相似不能复用另一篇 MOPD 的代码或结论。',
 ['只看大小写就能区分两篇工作吗？','不能。应以全称、来源和具体机制确认。']),
g('rewardx','当前只有一个未核实的内部名称，尚不能确定是奖励模型、数据流水线、平台还是算法。先定位证据，比虚构一个定义更有用。',
 ['看到公司菜单上的“X 套餐”，不知道里面是什么，就无法比较营养或价格；名称不是配方。','本条不是对某个确定模型的介绍，也不暗示 rewardx 必然存在统一公开定义。'],
 ['记录它在哪个页面、命令或配置中出现。','追踪输入输出：如果输出分数，仍需区分规则、模型和聚合器。','找到完整名字或官方说明后再建立训练链位置。'],
 ['保留拼写和上下文。','找定义处、调用处、数据与目标证据。','未知时写待确认，不套用 ImageReward 的机制。'],
 '避免把内部工具误当一种主流算法。','无法在未确认对象时给出算法优缺点或使用建议。',
 ['名字包含 reward，就说明用了强化学习吗？','不是。奖励可能只用于评测或筛数据，是否训练策略要看更新过程。'])
];
